'use client';

import type { Variants } from 'motion/react';
import { motion, useAnimation } from 'motion/react';
import type { HTMLAttributes } from 'react';
import { forwardRef } from 'react';
import { useIconAnimation } from '@/lib/use-icon-animation';
import { cn } from '@/lib/utils';

export interface CrownIconHandle {
  startAnimation: () => void;
  stopAnimation: () => void;
}

interface CrownIconProps extends HTMLAttributes<HTMLDivElement> {
  size?: number;
}

const CROWN_DURATION = 1.15;
const TWINKLES = [
  { x: 12, y: 7.4 },
  { x: 7.6, y: 13 },
  { x: 16.4, y: 13 },
];

// The crown dips, rises off its base with a little stretch, and is held up
// while three small twinkles flash inside it in turn. Then it sets back down
// with a soft landing. The base line and the center jewel stay fixed.
const crownVariants: Variants = {
  normal: { translateY: 0, scaleY: 1 },
  animate: {
    translateY: [0, 0.4, -1.7, -1.5, 0.25, 0],
    scaleY: [1, 0.95, 1.03, 1, 0.98, 1],
    transition: {
      duration: CROWN_DURATION,
      times: [0, 0.14, 0.34, 0.66, 0.84, 1],
      ease: ['easeInOut', [0.33, 1, 0.68, 1], 'easeInOut', [0.55, 0, 0.85, 0.35], 'easeOut'],
    },
  },
};

const generatedGeometryVariants: Variants = {
  normal: { visibility: 'hidden', transition: { duration: 0 } },
  animate: {
    visibility: ['visible', 'visible', 'hidden'],
    transition: { duration: CROWN_DURATION, times: [0, 0.82, 0.84] },
  },
};

const twinkleVariants: Variants = {
  normal: { scale: 0, rotate: 0 },
  animate: (i: number) => ({
    scale: [0, 0, 1, 0, 0],
    rotate: [0, 0, 45, 90, 90],
    transition: {
      duration: CROWN_DURATION,
      times: [0, 0.3 + i * 0.09, 0.4 + i * 0.09, 0.52 + i * 0.09, 1],
      ease: 'easeInOut',
    },
  }),
};

const CrownIcon = forwardRef<CrownIconHandle, CrownIconProps>(
  ({ onMouseEnter, onMouseLeave, className, size = 28, ...props }, ref) => {
    const controls = useAnimation();
    const { handleMouseEnter, handleMouseLeave } = useIconAnimation({
      controls,
      loops: false,
      onMouseEnter,
      onMouseLeave,
      ref,
    });

    return (
      <div
        className={cn(className)}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        {...props}
      >
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width={size}
          height={size}
          viewBox="0 0 24 24"
          fill="none"
          overflow="visible"
        >
          <path
            d="M5 21H19"
            stroke="currentColor"
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth="1.5"
          />
          <path
            d="M12.125 12.75H12M12.25 12.75C12.25 12.8881 12.1381 13 12 13C11.8619 13 11.75 12.8881 11.75 12.75C11.75 12.6119 11.8619 12.5 12 12.5C12.1381 12.5 12.25 12.6119 12.25 12.75Z"
            stroke="currentColor"
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth="1.5"
          />
          <motion.g
            variants={crownVariants}
            animate={controls}
            initial="normal"
            style={{ transformBox: 'view-box', originX: 0.5, originY: 17 / 24 }}
          >
            <motion.g
              variants={generatedGeometryVariants}
              animate={controls}
              initial="normal"
            >
              {TWINKLES.map(({ x, y }, i) => (
                <motion.path
                  key={i}
                  d={`M${x} ${y - 0.9}V${y + 0.9}M${x - 0.9} ${y}H${x + 0.9}`}
                  stroke="currentColor"
                  strokeLinecap="round"
                  strokeWidth="1.5"
                  variants={twinkleVariants}
                  custom={i}
                  animate={controls}
                  initial="normal"
                  style={{ transformBox: 'view-box', originX: x / 24, originY: y / 24 }}
                />
              ))}
            </motion.g>
            <path
              d="M14.9152 7.61089L13.8078 5.38179C13.019 3.79393 12.6246 3 12 3C11.3754 3 10.981 3.79393 10.1922 5.38179L9.08483 7.61089C8.58107 8.62494 8.32919 9.13197 7.87976 9.24608C7.8485 9.25401 7.81689 9.26043 7.78503 9.26533C7.32682 9.3357 6.89919 8.96678 6.04393 8.22895C4.0124 6.47635 2.99663 5.60004 2.38034 5.94899C2.34045 5.97157 2.30213 5.99686 2.26565 6.02467C1.70197 6.45439 2.09541 7.74136 2.88229 10.3153L4.04783 14.1279C4.47098 15.5121 4.68255 16.2042 5.21787 16.6021C5.75318 17 6.47261 17 7.91147 17L16.0886 16.9999C17.5274 16.9999 18.2468 16.9999 18.7821 16.602C19.3175 16.2041 19.529 15.512 19.9522 14.1279L21.1177 10.3153C21.9046 7.74137 22.298 6.4544 21.7344 6.02468C21.6979 5.99687 21.6595 5.97158 21.6197 5.94899C21.0034 5.60006 19.9876 6.47636 17.9561 8.22896C17.1008 8.96679 16.6732 9.3357 16.215 9.26533C16.1831 9.26043 16.1515 9.25401 16.1202 9.24607C15.6708 9.13197 15.4189 8.62494 14.9152 7.61089Z"
              stroke="currentColor"
              strokeLinecap="round"
              strokeLinejoin="round"
              strokeWidth="1.5"
            />
          </motion.g>
        </svg>
      </div>
    );
  }
);

CrownIcon.displayName = 'CrownIcon';

export { CrownIcon };

'use client';

import type { LegacyAnimationControls } from 'motion/react';
import { spring, useReducedMotion } from 'motion/react';
import type {
  ForwardedRef,
  MouseEventHandler,
} from 'react';
import { useCallback, useImperativeHandle, useRef } from 'react';

/**
 * A damped spring as the easing of one keyframe segment: the value overshoots
 * its target and settles on it. Use it for landings so every icon shares the
 * same physical bounce. Higher `bounce` gives more oscillation.
 */
export function springEase(bounce = 0.45, visualDuration = 0.35) {
  const generator = spring({ keyframes: [0, 1], bounce, visualDuration });
  let settle = 0;
  while (!generator.next(settle).done && settle < 5000) settle += 10;
  return (progress: number) =>
    progress >= 1 ? 1 : generator.next(progress * settle).value;
}

/**
 * One wave of a looping wave train, like sound leaving a speaker. The wave
 * fades in at the first pose, moves through each pose at an even pace, fades
 * out at the last, and returns hidden to the first. Give each wave the pose it
 * rests on; waves on neighbouring poses then move as one train. All poses must
 * share the same path commands.
 */
export function waveTrain(poses: string[], rest: number, duration: number) {
  const last = poses.length - 1;
  const steps = [];
  for (let pose = rest; pose <= last; pose++) steps.push(pose);
  for (let pose = 0; rest > 0 && pose <= rest; pose++) steps.push(pose);
  return {
    d: steps.map((pose) => poses[pose]),
    opacity: steps.map((pose) => (pose === 0 || pose === last ? 0 : 1)),
    transition: {
      duration,
      ease: 'linear' as const,
      // The return from the last pose to the first is a hidden jump.
      times: steps.map((_, k) => {
        if (k <= last - rest) return k / last;
        return (k - 1) / last + (k === last - rest + 1 ? 0.001 : 0);
      }),
      repeat: Infinity,
    },
  };
}

export interface AnimatedIconHandle {
  startAnimation: () => void;
  stopAnimation: () => void;
}

interface UseIconAnimationOptions {
  controls: LegacyAnimationControls;
  loops?: boolean;
  onMouseEnter?: MouseEventHandler<HTMLDivElement>;
  onMouseLeave?: MouseEventHandler<HTMLDivElement>;
  ref: ForwardedRef<AnimatedIconHandle>;
}

export function useIconAnimation({
  controls,
  loops = false,
  onMouseEnter,
  onMouseLeave,
  ref,
}: UseIconAnimationOptions) {
  const shouldReduceMotion = useReducedMotion();
  const isControlledRef = useRef(false);
  const isPlayingRef = useRef(false);
  const runRef = useRef(0);

  const startAnimation = useCallback(() => {
    if (shouldReduceMotion || isPlayingRef.current) return;

    isPlayingRef.current = true;
    const run = ++runRef.current;
    controls.set('normal');
    void controls.start('animate').then(() => {
      if (runRef.current === run) isPlayingRef.current = false;
    });
  }, [controls, shouldReduceMotion]);

  const stopAnimation = useCallback(() => {
    if (!loops) return;

    runRef.current++;
    isPlayingRef.current = false;
    void controls.start('normal');
  }, [controls, loops]);

  useImperativeHandle(
    ref,
    () => {
      isControlledRef.current = true;
      return { startAnimation, stopAnimation };
    },
    [startAnimation, stopAnimation]
  );

  const handleMouseEnter = useCallback<MouseEventHandler<HTMLDivElement>>(
    (event) => {
      onMouseEnter?.(event);
      if (!isControlledRef.current) startAnimation();
    },
    [onMouseEnter, startAnimation]
  );

  const handleMouseLeave = useCallback<MouseEventHandler<HTMLDivElement>>(
    (event) => {
      onMouseLeave?.(event);
      if (!isControlledRef.current) stopAnimation();
    },
    [onMouseLeave, stopAnimation]
  );

  return { handleMouseEnter, handleMouseLeave };
}
